      <label>Largeur (m)</label><input type="range" id="rw" min="3" max="14" step="0.5" value="7"><label>Longueur (m)</label><input type="range" id="rl" min="3" max="16" step="0.5" value="8"><label>Hauteur (m)</label><input type="range" id="rh" min="2.4" max="4.2" step="0.1" value="3">
