<div class="modal" id="helpModal"><div class="box"><button class="btn close" onclick="document.getElementById('helpModal').style.display='none'">Fermer</button><h2 style="color:#f6d36b">GEA-H Studio 3D IA</h2><p>Cette section joue le rôle d’un assistant ingénieur de décoration et d’ameublement. L’utilisateur visualise l’intérieur, change les sols, murs, plafond, meubles et reçoit des propositions IA, puis ajuste lui-même.</p></div></div>
<script src="https://cdn.jsdelivr.net/npm/three@0.128.0/build/three.min.js"></script><script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"></script>
<script>
(function(){
var scene,camera,renderer,controls,raycaster,mouse,roomGroup,selected=null,dragging=false,plane=new THREE.Plane(new THREE.Vector3(0,1,0),0),photoTex=null,isNight=false;var room={w:7,l:8,h:3,floor:'epoxy',wall:'#efe8dc',ceil:'#ffffff'};var objs=[];
var stage=document.getElementById('stage'),cv=document.getElementById('c');var floorColors={epoxy:0x5ab5ff,marble:0xf4f1e9,tile:0xdfe4e8,wood:0x9a673f,concrete:0x8d9496,terrazzo:0xe9e3d8};
function mat(c,r,m){return new THREE.MeshStandardMaterial({color:c,roughness:r||.65,metalness:m||0});}
function init(){scene=new THREE.Scene();scene.background=new THREE.Color(0x0a1118);camera=new THREE.PerspectiveCamera(55,stage.clientWidth/stage.clientHeight,.1,200);camera.position.set(8,6,10);renderer=new THREE.WebGLRenderer({canvas:cv,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(stage.clientWidth,stage.clientHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;controls=new THREE.OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.target.set(0,1.3,0);scene.add(new THREE.HemisphereLight(0xffffff,0x2a332e,.7));var sun=new THREE.DirectionalLight(0xffefd0,1.05);sun.position.set(8,12,7);sun.castShadow=true;sun.shadow.mapSize.width=2048;sun.shadow.mapSize.height=2048;sun.shadow.camera.left=-20;sun.shadow.camera.right=20;sun.shadow.camera.top=20;sun.shadow.camera.bottom=-20;scene.add(sun);raycaster=new THREE.Raycaster();mouse=new THREE.Vector2();buildRoom();bind();animate();}
function buildRoom(){if(roomGroup)scene.remove(roomGroup);roomGroup=new THREE.Group();var w=room.w,l=room.l,h=room.h,t=.1;var wallM=mat(new THREE.Color(room.wall),.9,0),ceilM=mat(new THREE.Color(room.ceil),1,0),floorM=mat(floorColors[room.floor]||0x999999,room.floor==='epoxy'||room.floor==='marble'?.12:.75,room.floor==='epoxy'?.25:0);var floor=new THREE.Mesh(new THREE.BoxGeometry(w,.08,l),floorM);floor.position.y=-.04;floor.receiveShadow=true;floor.name='Sol';roomGroup.add(floor);if(room.floor==='epoxy'){var shine=new THREE.Mesh(new THREE.PlaneGeometry(w,l),new THREE.MeshStandardMaterial({color:0xffffff,transparent:true,opacity:.18,roughness:.04,metalness:.1}));shine.rotation.x=-Math.PI/2;shine.position.y=.012;shine.name='Reflet époxy';roomGroup.add(shine)}var ceil=new THREE.Mesh(new THREE.BoxGeometry(w,.06,l),ceilM);ceil.position.y=h;ceil.name='Plafond';roomGroup.add(ceil);
function wall(name,x,y,z,sx,sy,sz,rot){var m=(name==='Mur principal'&&photoTex)?new THREE.MeshStandardMaterial({map:photoTex,roughness:.85}):wallM;var mesh=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),m);mesh.position.set(x,y,z);if(rot)mesh.rotation.y=rot;mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.wall=true;mesh.name=name;roomGroup.add(mesh);return mesh}
wall('Mur principal',0,h/2,-l/2,w,h,t,0);wall('Mur entrée',0,h/2,l/2,w,h,t,0);wall('Mur gauche',-w/2,h/2,0,t,h,l,0);wall('Mur droit',w/2,h/2,0,t,h,l,0);
// porte et fenêtres en relief
var door=new THREE.Mesh(new THREE.BoxGeometry(1.05,2.05,.04),mat(0x6b4727,.75,0));door.position.set(-1.4,1.025,l/2+.07);door.name='Porte';roomGroup.add(door);var winM=new THREE.MeshStandardMaterial({color:0x9fd8ff,transparent:true,opacity:.45,roughness:.05});[['Fenêtre principale',1.6,1.55,l/2+.08,1.5,.85,.04],['Fenêtre gauche',-w/2-.08,1.55,-1.6,.04,.85,1.3]].forEach(function(a){var g=new THREE.Mesh(new THREE.BoxGeometry(a[4],a[5],a[6]),winM);g.position.set(a[1],a[2],a[3]);g.name=a[0];roomGroup.add(g)});
scene.add(roomGroup);updateStats();}
function furnitureMesh(type){var g=new THREE.Group();var m1=mat(0xd7b27b,.65,0),m2=mat(0x244a64,.55,0),m3=mat(0xf4f1e8,.55,0);function cube(n,s,p,m){var x=new THREE.Mesh(new THREE.BoxGeometry(s[0],s[1],s[2]),m);x.position.set(p[0],p[1],p[2]);x.castShadow=x.receiveShadow=true;x.name=n;g.add(x)}
if(type==='canape'){cube('Assise canapé',[2.2,.35,.85],[0,.35,0],m2);cube('Dossier canapé',[2.2,.9,.22],[0,.8,-.38],m2);cube('Accoudoir G',[.22,.65,.85],[-1.2,.55,0],m2);cube('Accoudoir D',[.22,.65,.85],[1.2,.55,0],m2)}
else if(type==='fauteuil'){cube('Fauteuil',[.9,.55,.85],[0,.45,0],m2);cube('Dossier',[.9,.9,.2],[0,.85,-.38],m2)}
else if(type==='table'){cube('Plateau table',[1.2,.12,.7],[0,.75,0],m1);cube('Pied',[.18,.75,.18],[0,.35,0],m1)}
else if(type==='lit'){cube('Lit',[2.1,.35,1.55],[0,.35,0],m3);cube('Tête de lit',[2.1,1,.18],[0,.85,-.78],m1)}
else if(type==='tv'){cube('Meuble TV',[1.8,.35,.35],[0,.25,0],m1);cube('Écran TV',[1.45,.85,.06],[0,1.05,-.22],mat(0x050505,.3,0))}
else if(type==='cuisine'){cube('Cuisine moderne',[2.6,.9,.55],[0,.45,0],m3);cube('Plan travail',[2.6,.08,.6],[0,.93,0],mat(0x222222,.35,0));cube('Éléments hauts',[2.3,.75,.38],[0,1.75,-.18],m3)}
else if(type==='dressing'){cube('Dressing',[1.7,2.1,.45],[0,1.05,0],m1);cube('Miroir',[.55,1.7,.04],[.35,1.08,.24],mat(0xbfe9ff,.12,.1))}
else if(type==='plante'){cube('Pot',[.45,.45,.45],[0,.22,0],mat(0x7c4a25,.7,0));var s=new THREE.Mesh(new THREE.SphereGeometry(.55,16,12),mat(0x2f8c42,.9,0));s.position.y=1.0;s.castShadow=true;g.add(s)}
g.userData.type=type;g.name=type;return g;}
var furns=[['canape','Canapé'],['fauteuil','Fauteuil'],['table','Table'],['lit','Lit'],['tv','TV'],['cuisine','Cuisine'],['dressing','Dressing'],['plante','Plante']];var furn=document.getElementById('furn');furns.forEach(function(f){var b=document.createElement('button');b.className='choice';b.textContent=f[1];b.onclick=function(){addObj(f[0])};furn.appendChild(b)});
function addObj(type,pos){var o=furnitureMesh(type);o.position.copy(pos||new THREE.Vector3((Math.random()-.5)*2,.02,(Math.random()-.5)*2));scene.add(o);objs.push(o);select(o);updateStats();}
function select(o){selected=o;document.getElementById('selInfo').innerHTML=o?('<b>'+o.name+'</b><br>Déplacez, tournez ou supprimez cet élément.'):('Aucun objet sélectionné.');}
function setMouse(e){var r=renderer.domElement.getBoundingClientRect();mouse.x=((e.clientX-r.left)/r.width)*2-1;mouse.y=-((e.clientY-r.top)/r.height)*2+1;}
function pick(e){setMouse(e);raycaster.setFromCamera(mouse,camera);var hit=raycaster.intersectObjects(objs,true)[0];if(hit){var o=hit.object;while(o.parent&&!objs.includes(o))o=o.parent;return o}return null;}
function onDown(e){var p=pick(e);if(p){select(p);dragging=true;controls.enabled=false}else select(null)}function onMove(e){if(!dragging||!selected)return;setMouse(e);raycaster.setFromCamera(mouse,camera);var pt=new THREE.Vector3();raycaster.ray.intersectPlane(plane,pt);selected.position.x=Math.max(-room.w/2+.5,Math.min(room.w/2-.5,pt.x));selected.position.z=Math.max(-room.l/2+.5,Math.min(room.l/2-.5,pt.z));}function onUp(){dragging=false;controls.enabled=true}
function bind(){renderer.domElement.addEventListener('pointerdown',onDown);renderer.domElement.addEventListener('pointermove',onMove);addEventListener('pointerup',onUp);addEventListener('resize',resize);['rw','rl','rh','floor','wall','ceil'].forEach(function(id){document.getElementById(id).oninput=function(){room.w=+rw.value;room.l=+rl.value;room.h=+rh.value;room.floor=floor.value;room.wall=wall.value;room.ceil=ceil.value;scene.remove(roomGroup);buildRoom();}});document.getElementById('rot').onclick=function(){if(selected)selected.rotation.y+=Math.PI/4};document.getElementById('up').onclick=function(){if(selected)selected.position.y+=.1};document.getElementById('down').onclick=function(){if(selected)selected.position.y=Math.max(0,selected.position.y-.1)};document.getElementById('del').onclick=function(){if(selected){scene.remove(selected);objs=objs.filter(function(o){return o!==selected});select(null);updateStats();}};document.getElementById('viewInside').onclick=function(){camera.position.set(0,1.65,room.l/2-1.2);controls.target.set(0,1.55,-room.l/2+.7)};document.getElementById('viewTop').onclick=function(){camera.position.set(0,16,.1);controls.target.set(0,0,0)};document.getElementById('viewFace').onclick=function(){camera.position.set(room.w*1.35,room.h*1.1,room.l*1.35);controls.target.set(0,room.h/2,0)};document.getElementById('viewPersp').onclick=function(){camera.position.set(8,6,10);controls.target.set(0,1.3,0)};document.getElementById('dayNight').onclick=function(){isNight=!isNight;scene.background=new THREE.Color(isNight?0x050711:0x0a1118);this.textContent=isNight?'☀️ Jour':'🌙 Nuit'};document.getElementById('fullscreen').onclick=function(){(stage.requestFullscreen||stage.webkitRequestFullscreen).call(stage)};document.getElementById('photo').onchange=function(e){var file=e.target.files[0];if(!file)return;var url=URL.createObjectURL(file);new THREE.TextureLoader().load(url,function(t){photoTex=t;photoTex.wrapS=photoTex.wrapT=THREE.ClampToEdgeWrapping;});};document.getElementById('usePhotoWall').onclick=function(){scene.remove(roomGroup);buildRoom()};document.getElementById('aiSuggest').onclick=aiSuggest;document.getElementById('aiApply').onclick=aiApply;document.getElementById('save').onclick=save;document.getElementById('load').onclick=load;document.getElementById('png').onclick=png;document.getElementById('reset').onclick=function(){localStorage.removeItem('geah_studio3d_ai');location.reload()};document.getElementById('presetSalon').onclick=function(){clearObjs();addObj('canape',new THREE.Vector3(0,.02,1));addObj('table',new THREE.Vector3(0,.02,0));addObj('tv',new THREE.Vector3(0,.02,-room.l/2+.45));addObj('plante',new THREE.Vector3(room.w/2-.8,.02,-room.l/2+.8));};document.getElementById('presetChambre').onclick=function(){clearObjs();addObj('lit',new THREE.Vector3(0,.02,-1));addObj('dressing',new THREE.Vector3(room.w/2-.8,.02,1));addObj('table',new THREE.Vector3(-1.4,.02,-1));};document.getElementById('presetCuisine').onclick=function(){clearObjs();addObj('cuisine',new THREE.Vector3(0,.02,-room.l/2+.7));addObj('table',new THREE.Vector3(0,.02,1.2));};document.getElementById('presetBureau').onclick=function(){clearObjs();addObj('table',new THREE.Vector3(0,.02,0));addObj('fauteuil',new THREE.Vector3(0,.02,1));addObj('plante',new THREE.Vector3(-room.w/2+.8,.02,-room.l/2+.8));};}
function clearObjs(){objs.forEach(function(o){scene.remove(o)});objs=[];select(null);updateStats()}
function aiSuggest(){var p=document.getElementById('aiPrompt').value.toLowerCase();var luxury=p.includes('luxe')||p.includes('or')||p.includes('premium');var epoxy=p.includes('epoxy')||p.includes('brillant');var modern=p.includes('moderne')||p.includes('minimal');document.getElementById('aiOut').innerHTML='<b>Proposition IA GEA-H :</b><br>'+ (luxury?'Style blanc, or et bois clair. Ajoutez canapé central, table basse, TV murale, plantes, lumière chaude et sol marbre ou époxy.<br>':'Style équilibré : circulation dégagée, mobilier principal au centre, éclairage doux, couleurs calmes.<br>') + (epoxy?'Sol recommandé : résine époxy brillante avec reflets pour un rendu premium.<br>':'Sol recommandé : parquet ou carrelage clair selon budget.<br>') + (modern?'Conseil : réduire les meubles, garder des lignes droites et une palette claire.':'Conseil : garder un mur accent et un mobilier confortable.');}
function aiApply(){var p=document.getElementById('aiPrompt').value.toLowerCase();if(p.includes('or')||p.includes('luxe')){wall.value='#f7f2e8';ceil.value='#ffffff';floor.value='marble'}else if(p.includes('epoxy')){floor.value='epoxy';wall.value='#eef5f8'}else if(p.includes('bois')){floor.value='wood';wall.value='#f2eadf'}room.w=+rw.value;room.l=+rl.value;room.h=+rh.value;room.floor=floor.value;room.wall=wall.value;room.ceil=ceil.value;buildRoom();clearObjs();addObj('canape',new THREE.Vector3(0,.02,1));addObj('table',new THREE.Vector3(0,.02,0));addObj('tv',new THREE.Vector3(0,.02,-room.l/2+.5));addObj('plante',new THREE.Vector3(room.w/2-.8,.02,-room.l/2+.8));}
function updateStats(){var area=room.w*room.l;var base={epoxy:18000,marble:25000,tile:9000,wood:14000,concrete:12000,terrazzo:16000}[room.floor]||10000;var furnCost=objs.length*85000;document.getElementById('stats').innerHTML='<div class="stat"><span>Surface</span><b>'+area.toFixed(1)+' m²</b></div><div class="stat"><span>Sol estimé</span><b>'+Math.round(area*base).toLocaleString('fr-FR')+' FCFA</b></div><div class="stat"><span>Mobilier estimé</span><b>'+furnCost.toLocaleString('fr-FR')+' FCFA</b></div><div class="stat"><span>Total indicatif</span><b style="color:#f6d36b">'+Math.round(area*base+furnCost).toLocaleString('fr-FR')+' FCFA</b></div>'}
function save(){var data={room:room,objs:objs.map(function(o){return{type:o.userData.type,x:o.position.x,y:o.position.y,z:o.position.z,r:o.rotation.y}})};localStorage.setItem('geah_studio3d_ai',JSON.stringify(data));alert('Projet enregistré sur cet appareil.')}function load(){var s=localStorage.getItem('geah_studio3d_ai');if(!s)return alert('Aucun projet enregistré.');var d=JSON.parse(s);room=d.room||room;rw.value=room.w;rl.value=room.l;rh.value=room.h;floor.value=room.floor;wall.value=room.wall;ceil.value=room.ceil;buildRoom();clearObjs();(d.objs||[]).forEach(function(a){var o=furnitureMesh(a.type);o.position.set(a.x,a.y,a.z);o.rotation.y=a.r||0;scene.add(o);objs.push(o)});updateStats();}function png(){renderer.render(scene,camera);var a=document.createElement('a');a.download='gea-h-studio-3d-amenagement.png';a.href=renderer.domElement.toDataURL('image/png');a.click()}
function resize(){renderer.setSize(stage.clientWidth,stage.clientHeight);camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix()}function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)}init();})();
</script></body></html>
